// Cosmetic state has its own RNG and never changes combat, drops or skill choices.
export const EFFECT_LIMITS={sparks:420,impacts:72,ghosts:48,muzzles:24,shockwaves:18,glass:96};
export class CombatEffects{
 constructor(){this.seed=8173;this.sparks=[];this.impacts=[];this.ghosts=[];this.muzzles=[];this.shockwaves=[];this.glass=[];this.pulse=null;this.reward=null;this.kick=0;this.bucket=0;this.batchKills=0;this.batchPoints=0;this.batchX=0;this.batchY=0;this.clock=0;this.nextKick=0;this.nextAccent=0;this.hitSound=0;}
 random(){this.seed=(Math.imul(this.seed,1664525)+1013904223)>>>0;return this.seed/4294967296;}
 add(key,item){if(this[key].length>=EFFECT_LIMITS[key])this[key].shift();this[key].push(item);}
 scatter(x,y,n,color,speed=190,angle=0,spread=Math.PI*2){for(let i=0;i<n;i++){const a=angle+(this.random()-.5)*spread,v=speed*(.35+this.random()*.65),life=.2+this.random()*.28;this.add('sparks',{x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life,maxLife:life,color,size:2+this.random()*3});}}
 punch(strength){if(this.clock<this.nextKick)return;this.kick=Math.max(this.kick,strength);this.nextKick=this.clock+.16;}
 hit(enemy,amount,player,time,options={}){if(time<(enemy.nextImpact||0))return;enemy.nextImpact=time+.09;const a=Number.isFinite(options.impactAngle)?options.impactAngle:Math.atan2(enemy.y-player.y,enemy.x-player.x),heavy=amount>=60,color=heavy?'#ffd46b':'#79ffe0';enemy.impactAngle=a;enemy.impactAt=time;enemy.impactStrength=enemy.kind==='boss'?2:heavy?6:3;const x=enemy.x-Math.cos(a)*enemy.r*.65,y=enemy.y-Math.sin(a)*enemy.r*.65-5;this.add('impacts',{x,y,r:heavy?44:29,angle:a,color,kind:'hit',life:.2,maxLife:.2});this.scatter(x,y,heavy?7:4,color,heavy?370:270,a,1.9);this.hitSound=Math.max(this.hitSound,heavy?2:1);}
 shatter(x,y,angle){
  for(let i=0;i<8;i++){const a=angle+(this.random()-.5)*Math.PI*2,speed=45+this.random()*135,life=.5+this.random()*.3;this.add('glass',{x,y,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,height:3,vz:65+this.random()*85,angle:this.random()*Math.PI,spin:(this.random()-.5)*14,size:3+this.random()*4,life,maxLife:life});}
  this.scatter(x,y,7,'#ffb85b',130);this.add('impacts',{x,y,r:25,angle,color:'#ffe4a1',kind:'hit',life:.16,maxLife:.16});
 }
 fire(x,y,angle,color='#aefbe0',heavy=false){x+=Math.cos(angle)*14-Math.sin(angle)*7;y+=Math.sin(angle)*14+Math.cos(angle)*7-6;this.add('muzzles',{x:x+Math.cos(angle)*28,y:y+Math.sin(angle)*28,angle,color,r:heavy?47:28,life:heavy?.15:.1,maxLife:heavy?.15:.1});if(heavy){this.scatter(x+Math.cos(angle)*32,y+Math.sin(angle)*32,5,color,300,angle,.75);this.punch(.22);}}
 kill(enemy,points,player){const a=Number.isFinite(enemy.impactAngle)?enemy.impactAngle:Math.atan2(enemy.y-player.y,enemy.x-player.x),big=['elite','boss'].includes(enemy.kind),color=enemy.kind==='ice'?'#79eaff':enemy.kind==='orange'?'#ffbc5b':'#dfa0ff';this.add('ghosts',{kind:enemy.kind,sprite:enemy.sprite,size:enemy.kind==='boss'?156:enemy.kind==='elite'?94:enemy.r*2.7,originX:enemy.x,originY:enemy.y,x:enemy.x,y:enemy.y,vx:Math.cos(a)*(big?115:230),vy:Math.sin(a)*(big?115:230)-95,angle:0,spin:(this.random()-.5)*7,r:enemy.r,life:big?.65:.42,maxLife:big?.65:.42});this.add('impacts',{x:enemy.x,y:enemy.y-5,r:big?115:53,angle:a,color,kind:'kill',life:big?.42:.32,maxLife:big?.42:.32});this.scatter(enemy.x,enemy.y,big?32:12,color,big?440:320);if(big)this.punch(.55);this.batchKills++;this.batchPoints+=points;this.batchX+=enemy.x;this.batchY+=enemy.y;if(!this.bucket)this.bucket=.18;}
 explosion(x,y,r,color='#ffda87'){this.add('shockwaves',{x,y,r,color,life:.55,maxLife:.55});this.add('impacts',{x,y,r:Math.min(r*.5,100),angle:0,color,kind:'kill',life:.26,maxLife:.26});this.scatter(x,y,24,color,430);this.punch(Math.min(.55,r/400));}
 celebrate(x,y,kind='evolution'){const color=kind==='boss'?'#ffe49a':'#b8ffeb';for(const [r,life] of [[160,.48],[290,.7],[420,.95]])this.add('shockwaves',{x,y,r,color,life,maxLife:life});this.scatter(x,y,65,color,460);this.pulse={kind,color,life:1,maxLife:1};this.kick=.85;}
 step(dt){
  this.clock+=dt;this.kick=Math.max(0,this.kick-dt*3);for(const key of ['impacts','muzzles','shockwaves']){for(const f of this[key])f.life-=dt;this[key]=this[key].filter(f=>f.life>0);}
  for(const f of this.sparks){f.life-=dt;f.x+=f.vx*dt;f.y+=f.vy*dt;const drag=Math.exp(-dt*4);f.vx*=drag;f.vy=f.vy*drag+80*dt;}this.sparks=this.sparks.filter(f=>f.life>0);
  for(const f of this.ghosts){f.life-=dt;f.x+=f.vx*dt;f.y+=f.vy*dt;f.vy+=180*dt;f.angle+=f.spin*dt;}this.ghosts=this.ghosts.filter(f=>f.life>0);
  for(const f of this.glass){f.life-=dt;f.x+=f.vx*dt;f.y+=f.vy*dt;f.height+=f.vz*dt;f.vz-=560*dt;f.angle+=f.spin*dt;if(f.height<0){f.height=0;f.vz=Math.abs(f.vz)*.22;f.vx*=.5;f.vy*=.5;}}this.glass=this.glass.filter(f=>f.life>0);
  if(this.pulse&&(this.pulse.life-=dt)<=0)this.pulse=null;if(this.reward&&(this.reward.life-=dt)<=0)this.reward=null;
  if(this.bucket>0){this.bucket-=dt;if(this.bucket<=0){this.bucket=0;const kills=this.batchKills,points=this.batchPoints,x=this.batchX/kills,y=this.batchY/kills;this.batchKills=this.batchPoints=this.batchX=this.batchY=0;if(kills>=3){const tier=kills>=15?3:kills>=8?2:1;this.reward={kills,points,tier,life:1.05,maxLife:1.05};if(this.clock>=this.nextAccent){this.add('shockwaves',{x,y,r:110+tier*45,color:tier===3?'#83ffe0':'#ffdf88',life:.45,maxLife:.45});this.punch(.23+tier*.08);this.nextAccent=this.clock+.55;}return {kills,points};}}}return null;
 }
}
